export class PublicSettingsController {
    constructor(readonly settingService: SettingsService) {}
    /**
     * Update Business Info and Logo.
     */
    @ApiOkResponse({
        status: 200,
        description: 'Updated Business Profile',
        type: ReadSettingsResponse,
