import { BadRequestException, Logger } from '@nestjs/common';
import { fromTemporaryCredentials } from '@aws-sdk/credential-providers';
import { serializeError } from 'serialize-error';
import { getInstanceWithFilters } from './awsEc2.js';

const logger = new Logger('ScraperRoleValidation');

/**
 * The session name used when MeteringCo validates a customer supplied scraper role.
 */
export const VALIDATION_ROLE_SESSION_NAME = 'meteringco-settings-validation';

/**
 * Message returned when the supplied role cannot be assumed with the supplied external id.
 */
export const UNASSUMABLE_IAM_ROLE_MESSAGE =
    'cloudIAM: Unable to assume the provided IAM role. Verify the IAM role ARN, its trust policy and the external ID provided';

/**
 * Message returned when the role can be assumed but the resulting credentials cannot read the
 * EC2 instance inventory that MeteringCo collection depends on.
 */
export const UNAUTHORIZED_IAM_ROLE_MESSAGE =
    'cloudIAM: The provided IAM role was assumed but it is not authorized to describe EC2 instances (ec2:DescribeInstances) which is required to collect usage';

/**
 * A scraper role which is an empty (or whitespace only) string means "disconnect".
 */
export const isDisconnectIamRole = (iamRoleArn?: unknown): boolean =>
    typeof iamRoleArn === 'string' && iamRoleArn.trim() === '';

/**
 * A cloudIAM settings block must always name a role, an absent/non string role is invalid input,
 * it is not the same thing as disconnecting.
 */
export const isMissingIamRole = (iamRoleArn?: unknown): boolean => typeof iamRoleArn !== 'string';

const defaultRegion = () => process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

/**
 * Assume a customer supplied scraper role with the supplied external id.
 *
 * @throws BadRequestException when the role cannot be assumed.
 */
export const assumeScraperRole = async ({
    iamRoleArn,
    externalId,
    region = defaultRegion(),
}: {
    iamRoleArn: string;
    externalId?: string;
    region?: string;
}) => {
    try {
        const credentialProvider = fromTemporaryCredentials({
            params: {
                RoleArn: iamRoleArn,
                ExternalId: externalId ? externalId : undefined,
                RoleSessionName: VALIDATION_ROLE_SESSION_NAME,
            },
            clientConfig: { region },
        });
        // Resolving the provider performs the sts:AssumeRole call
        return await credentialProvider();
    } catch (e) {
        logger.warn(
            `Failed to assume customer scraper role ${iamRoleArn}: ${JSON.stringify(serializeError(e as Error))}`,
        );
        throw new BadRequestException(UNASSUMABLE_IAM_ROLE_MESSAGE);
    }
};

/**
 * Validate that a customer supplied scraper role is usable by MeteringCo before it is persisted.
 *
 * Two things are proven:
 *  1. The role can be assumed by MeteringCo using the supplied external id.
 *  2. The credentials handed back by that assumption can read the EC2 instance inventory used
 *     by the collection microservices.
 *
 * Either failure is a bad request, so the caller must not persist anything.
 */
export const validateScraperRoleAccess = async ({
    iamRoleArn,
    externalId,
    region = defaultRegion(),
}: {
    iamRoleArn: string;
    externalId?: string;
    region?: string;
}): Promise<void> => {
    const credentials = await assumeScraperRole({ iamRoleArn, externalId, region });

    try {
        // The same inventory read the collection microservices perform
        await getInstanceWithFilters(region, credentials, [
            { Name: 'instance-state-name', Values: ['running'] },
        ]);
    } catch (e) {
        logger.warn(
            `Assumed customer scraper role ${iamRoleArn} cannot read the EC2 instance inventory: ${JSON.stringify(
                serializeError(e as Error),
            )}`,
        );
        throw new BadRequestException(UNAUTHORIZED_IAM_ROLE_MESSAGE);
    }
};
