            return true;
        }
        const { externalId } = (args?.object ?? {}) as { externalId?: string };
        try {
            await validateScraperRoleAccess({ iamRoleArn, externalId });
            return true;
        } catch (e) {
            if (args?.object) {
                failureReasons.set(args.object, (e as Error)?.message || UNASSUMABLE_IAM_ROLE_MESSAGE);
            }
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        return (args?.object && failureReasons.get(args.object)) || UNASSUMABLE_IAM_ROLE_MESSAGE;
    }
}

/**
 * Proves a customer supplied scraper role can be assumed with the supplied external id and that
 * the resulting credentials can read the instance inventory used by collection.
 */
export function UsableScraperRole(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'UsableScraperRole',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [],
            options: validationOptions,
            validator: UsableScraperRoleRule,
        });
    };
}
