/**
 * The session name used when MeteringCo validates a customer supplied scraper role.
 */
export const VALIDATION_ROLE_SESSION_NAME = 'meteringco-settings-validation';

/**
 * Message returned when the supplied role cannot be assumed with the supplied external id.
 */
export const UNASSUMABLE_IAM_ROLE_MESSAGE =
    'iamRoleArn: MeteringCo could not assume the provided IAM role, verify the IAM role ARN, its trust policy and the external ID provided';

/**
 * Message returned when the role can be assumed but the resulting credentials cannot read the
 * EC2 instance inventory that MeteringCo collection depends on.
 */
export const UNAUTHORIZED_IAM_ROLE_MESSAGE =
    'iamRoleArn: The provided IAM role was assumed but it is not authorized to read the EC2 instance inventory (ec2:DescribeInstances) MeteringCo collection requires';

/**
 * Message returned when a cloudIAM settings block does not name a role at all, which is invalid
 * input rather than a request to disconnect.
 */
export const MISSING_IAM_ROLE_MESSAGE =
    'iamRoleArn: a cloudIAM settings block must name an IAM role, send an empty iamRoleArn to disconnect';

/**
 * A scraper role which is an empty (or whitespace only) string means "disconnect".
 */
export const isDisconnectIamRole = (iamRoleArn?: unknown): boolean =>
    typeof iamRoleArn === 'string' && iamRoleArn.trim() === '';

/**
 * A cloudIAM settings block must always name a role, an absent/non string role is invalid input,
 * it is not the same thing as disconnecting.
 */
export const isMissingIamRole = (iamRoleArn?: unknown): boolean => typeof iamRoleArn !== 'string';

const defaultRegion = () => process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

/**
 * Assume a customer supplied scraper role with the supplied external id.
 *
 * @throws BadRequestException when the role cannot be assumed.
 */
export const assumeScraperRole = async ({
    iamRoleArn,
    externalId,
    region = defaultRegion(),
}: {
    iamRoleArn: string;
    externalId?: string;
    region?: string;
}) => {
    try {
        const credentialProvider = fromTemporaryCredentials({
            params: {
                RoleArn: iamRoleArn,
                ExternalId: externalId ? externalId : undefined,
                RoleSessionName: VALIDATION_ROLE_SESSION_NAME,
            },
            clientConfig: { region },
        });
        // Resolving the provider performs the sts:AssumeRole call
        return await credentialProvider();
